def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_sizes = [row_bounds[i + 1] - row_bounds[i] - 1 for i in range(len(row_bounds) - 1)]
    col_sizes = [col_bounds[i + 1] - col_bounds[i] - 1 for i in range(len(col_bounds) - 1)]
    tile_h, tile_w = min(row_sizes), min(col_sizes)

    out = [row[:] for row in grid]
    marks = []
    for r in range(h):
        for c in range(w):
            if r not in sep_rows and c not in sep_cols and grid[r][c] != bg:
                marks.append((r % (tile_h + 1), c % (tile_w + 1), grid[r][c]))

    for r in range(h):
        for c in range(w):
            if r in sep_rows or c in sep_cols:
                continue
            for rr, cc, value in marks:
                if r % (tile_h + 1) == rr and c % (tile_w + 1) == cc:
                    out[r][c] = value
                    break
    return out
